mapper.select:
SELECT *
FROM (
    SELECT paged.*, ROWNUM AS rn
    FROM (


        WHERE (m.user1_id = #{userId} OR m.user2_id = #{userId})
          AND (
                  m.status = 'ACTIVE'
               OR (m.status = 'CANCELLED' AND m.cancelled_by != #{userId})
              )


        ORDER BY NVL(m.last_message_at, m.matched_at) DESC
    ) paged
    WHERE ROWNUM <= #{offset} + #{size}
)
WHERE rn > #{offset}


ORDER BY rn

SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END
FROM mingle_matches
WHERE user1_id = #{user1Id}
  AND user2_id = #{user2Id}
  AND status   = 'ACTIVE'

SELECT CASE WHEN user1_id = #{userId} THEN user2_id ELSE user1_id END
FROM mingle_matches
WHERE id = #{matchId}
